"% Clear workspace and define s variable
s = tf('s');

% --- INNER LOOP ---
% Plant G_in(s) = 1 / (s * (s + 4.0))
G_in = 1 / (s * (s + 4.0));

% Feedback gain ki = 9.0
ki = 9.0;

% Closed Inner Loop G_in_cl(s) = ki * G_in(s) / (1 + ki * G_in(s))
% Using feedback command for unity negative feedback
G_in_cl = feedback(ki * G_in, 1);

% --- OUTER LOOP ---
% Plant/Compensator G_out(s) = 3.0 / (s * (s + 4.0))
G_out = 3.0 / (s * (s + 4.0));

% --- TOTAL OPEN LOOP ---
% Cascaded total open loop L(s) = G_out(s) * G_in_cl(s)
L_total = G_out * G_in_cl;

% --- STABILITY MARGINS ---
% Compute gain margin (Gm), phase margin (Pm), 
% phase crossover frequency (Wgm), and gain crossover frequency (Wpm).
% Note: 
% Wgm is the frequency where phase is -180 degrees (Phase Crossover).
% Wpm is the frequency where gain is 1 (0 dB) (Gain Crossover).
[Gm, Pm, Wgm, Wpm] = margin(L_total);

% Convert Gain Margin to dB
gm_db_val = 20 * log10(Gm);

% --- SAVE RESULTS ---
% Map results to the required keys
% w_gc corresponds to Gain Crossover Frequency (Wpm)
% w_pc corresponds to Phase Crossover Frequency (Wgm)
result = struct();
result.gm_db = gm_db_val;
result.pm_deg = Pm;
result.w_gc = Wpm;
result.w_pc = Wgm;

% Write to result.json
fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
